package db

import (
	"database/sql"
	"database/sql/driver"
	"fmt"
	"net"
	"net/url"
	"path/filepath"
	"strconv"

	"github.com/go-sql-driver/mysql"
	"github.com/lib/pq"
	"github.com/luna-duclos/instrumentedsql"
	"github.com/luna-duclos/instrumentedsql/opentracing"
	"github.com/markphelps/flipt/config"
	"github.com/mattn/go-sqlite3"
	"github.com/xo/dburl"
)

// Open opens a database using the URL or individual settings in cfg.
func Open(cfg config.Config) (*sql.DB, Driver, error) {
	sql, driver, err := openConfig(cfg.Database, false)
	if err != nil {
		return nil, 0, err
	}

	registerMetrics(driver, sql)

	return sql, driver, nil
}

// openConfig is shared by normal connections and migrations so both paths use
// the same precedence, validation, and pool settings.
func openConfig(cfg config.DatabaseConfig, migrate bool) (*sql.DB, Driver, error) {
	if err := cfg.Validate(); err != nil {
		return nil, 0, fmt.Errorf("validating database configuration: %w", err)
	}

	rawurl := cfg.URL
	if rawurl == "" {
		rawurl = databaseURL(cfg)
	}

	db, driver, err := open(rawurl, migrate)
	if err != nil {
		return nil, 0, err
	}

	db.SetMaxIdleConns(cfg.MaxIdleConn)
	if cfg.MaxOpenConn > 0 {
		db.SetMaxOpenConns(cfg.MaxOpenConn)
	}
	if cfg.ConnMaxLifetime > 0 {
		db.SetConnMaxLifetime(cfg.ConnMaxLifetime)
	}

	return db, driver, nil
}

// databaseURL builds a URL for the existing driver-specific parser. cfg has
// already been validated, so a missing port denotes the engine default.
func databaseURL(cfg config.DatabaseConfig) string {
	switch cfg.Protocol {
	case config.SQLite:
		dir := cfg.Path
		if dir == "" {
			dir = cfg.Host
		}
		return (&url.URL{Scheme: "file", Path: filepath.Join(dir, cfg.Name)}).String()
	case config.Postgres, config.MySQL:
		port := cfg.Port
		if port == 0 {
			if cfg.Protocol == config.Postgres {
				port = 5432
			} else {
				port = 3306
			}
		}

		u := &url.URL{
			Scheme: cfg.Protocol.String(),
			Host:   net.JoinHostPort(cfg.Host, strconv.Itoa(port)),
			Path:   "/" + cfg.Name,
		}
		if cfg.Password != "" {
			u.User = url.UserPassword(cfg.User, cfg.Password)
		} else if cfg.User != "" {
			u.User = url.User(cfg.User)
		}
		return u.String()
	default:
		// DatabaseConfig.Validate rejects unknown protocols before this point.
		return ""
	}
}

func open(rawurl string, migrate bool) (*sql.DB, Driver, error) {
	d, target, err := parse(rawurl, migrate)
	if err != nil {
		return nil, 0, err
	}

	driverName := fmt.Sprintf("instrumented-%s", d)

	var dr driver.Driver

	switch d {
	case SQLite:
		dr = &sqlite3.SQLiteDriver{}
	case Postgres:
		dr = &pq.Driver{}
	case MySQL:
		dr = &mysql.MySQLDriver{}
	}

	registered := false

	for _, dd := range sql.Drivers() {
		if dd == driverName {
			registered = true
			break
		}
	}

	if !registered {
		sql.Register(driverName, instrumentedsql.WrapDriver(dr, instrumentedsql.WithTracer(opentracing.NewTracer(false))))
	}

	db, err := sql.Open(driverName, target.DSN)
	if err != nil {
		// Drivers can include the DSN (and its password) in parse errors.
		return nil, 0, fmt.Errorf("opening %s database connection: invalid connection settings", d)
	}

	return db, d, nil
}

var (
	driverToString = map[Driver]string{
		SQLite:   "sqlite3",
		Postgres: "postgres",
		MySQL:    "mysql",
	}

	stringToDriver = map[string]Driver{
		"sqlite3":  SQLite,
		"postgres": Postgres,
		"mysql":    MySQL,
	}
)

// Driver represents a database driver
type Driver uint8

func (d Driver) String() string {
	return driverToString[d]
}

const (
	_ Driver = iota
	// SQLite ...
	SQLite
	// Postgres ...
	Postgres
	// MySQL ...
	MySQL
)

func parse(rawurl string, migrate bool) (Driver, *dburl.URL, error) {
	url, err := dburl.Parse(rawurl)
	if err != nil {
		// dburl errors may contain the original URL, including userinfo.
		return 0, nil, fmt.Errorf("parsing db.url: invalid database URL")
	}

	driver := stringToDriver[url.Driver]
	if driver == 0 {
		return 0, nil, fmt.Errorf("validating db.url: unsupported database protocol %q (expected sqlite, postgres, mysql)", url.Driver)
	}

	switch driver {
	case MySQL:
		v := url.Query()
		v.Set("multiStatements", "true")
		v.Set("parseTime", "true")
		if !migrate {
			v.Set("sql_mode", "ANSI")
		}
		url.RawQuery = v.Encode()
		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())

	case SQLite:
		v := url.Query()
		v.Set("cache", "shared")
		v.Set("_fk", "true")
		url.RawQuery = v.Encode()

		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())
	}

	if err != nil {
		return 0, nil, fmt.Errorf("parsing db.url options for %s: invalid database URL", driver)
	}

	return driver, url, nil
}

